package com.aistock.prediction.explanation;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.ArrayNode;import java.util.*;import java.util.regex.*;
public final class ExplanationTemplate {
 private static final Pattern SLOT=Pattern.compile("\\{\\{([A-Z][A-Z0-9_]{0,31})\\}\\}");
 private static final Pattern UNSAFE=Pattern.compile("[0-9０-９<>\\p{Cntrl}]|[零〇一二三四五六七八九十百千万亿两]+(?:日|天|元|成|倍|个|次|只|%)|高于|低于|等于|上行|下行|上涨|下跌|上升|下降|百分之|买入|卖出|加仓|清仓|稳赚|必赚|保证收益|确定上涨|必然|buy|sell",Pattern.CASE_INSENSITIVE);
 private static final org.slf4j.Logger LOG=org.slf4j.LoggerFactory.getLogger(ExplanationTemplate.class);
 public static ArrayNode render(JsonNode input,Map<String,String> facts,ObjectMapper mapper){if(input==null||!input.isObject()||input.size()!=1||!input.path("paragraphs").isArray()||input.path("paragraphs").size()!=3)throw invalid("ROOT_SHAPE");var byKind=new HashMap<String,JsonNode>();for(var p:input.path("paragraphs")){String kind=p.path("kind").asText();if(!p.isObject()||p.size()!=3||!Set.of("overview","readout","risk").contains(kind)||byKind.put(kind,p)!=null)throw invalid("PARAGRAPH_SHAPE");}var rendered=mapper.createArrayNode();for(String kind:List.of("overview","readout","risk")){var p=byKind.get(kind);String template=p.path("template").asText();if(!p.path("template").isTextual()||template.isBlank()||template.length()>500||!p.path("refs").isArray())throw invalid("TEMPLATE_SHAPE_OR_LENGTH");var slots=new LinkedHashSet<String>();var matcher=SLOT.matcher(template);var out=new StringBuffer();while(matcher.find()){String id=matcher.group(1);if(!facts.containsKey(id))throw invalid("UNKNOWN_PLACEHOLDER");slots.add(id);matcher.appendReplacement(out,Matcher.quoteReplacement(facts.get(id)));}matcher.appendTail(out);String plain=SLOT.matcher(template).replaceAll("");if(plain.contains("{")||plain.contains("}"))throw invalid("MALFORMED_PLACEHOLDER");var unsafe=UNSAFE.matcher(plain);if(unsafe.find()){LOG.warn("Explanation rejected category={}",unsafeCategory(unsafe.group()));throw invalid("UNSAFE_LITERAL");}var declared=new LinkedHashSet<String>();for(var ref:p.path("refs")){if(!ref.isTextual()||!facts.containsKey(ref.asText())||!declared.add(ref.asText()))throw invalid("UNKNOWN_OR_DUPLICATE_REFERENCE");}if(slots.isEmpty()||!slots.equals(declared))throw invalid("REFERENCE_MISMATCH");var item=rendered.addObject().put("kind",kind).put("text",out.toString());item.set("refs",mapper.valueToTree(declared));}return rendered;}
 static String unsafeCategory(String token){if(token.matches("[0-9０-９]"))return "NUMBER";if(token.matches("[<>\\p{Cntrl}]"))return "HTML_OR_CONTROL";if(Set.of("高于","低于","等于","上行","下行","上涨","下跌","上升","下降","百分之").contains(token))return "DIRECTION";if(token.matches("[零〇一二三四五六七八九十百千万亿两]+(?:日|天|元|成|倍|个|次|只|%)"))return "QUANTITY";return "TRADING";}
 static com.aistock.common.BusinessException invalid(String reason){LOG.warn("Explanation rejected rule={}",reason);return invalid();}
 static com.aistock.common.BusinessException invalid(){return new com.aistock.common.BusinessException("AI_OUTPUT_INVALID","AI解释未通过一致性核验，原预测保留",org.springframework.http.HttpStatus.UNPROCESSABLE_ENTITY);}
}
